begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table restricted_fixture(id uuid);grant select,insert,update on restricted_fixture to cuevo_api;
insert into app.entitlements(school_id,code,enabled,effective_from)values('10000000-0000-4000-8000-000000000001','restricted.records',true,now()-interval'1 day')on conflict(school_id,code)do nothing;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99610000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Restricted factual source','Synthetic only','PUBLISHED');
-- Rollback-only disabled policy isolates this suite from prior synthetic browser approval.
insert into app.restricted_record_policies(school_id,version,enabled,purpose,source_basis,retention_status,retention_note,owner_id,reason,approved_by)select '10000000-0000-4000-8000-000000000001',coalesce(max(version),0)+1,false,'BASIC_INCIDENT_NOTE','SCHOOL_AUTHORED','SYNTHETIC_ONLY','Rollback fixture human owner retention review','20000000-0000-4000-8000-000000000001','Rollback-only synthetic deny state','20000000-0000-4000-8000-000000000001'from app.restricted_record_policies where school_id='10000000-0000-4000-8000-000000000001';
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.read_restricted_records(25,null)$$,'42501',null,'absent restricted policy disables note enumeration');select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select internal.restricted_record_command('policy',null,jsonb_build_object('enabled',true,'expectedVersion',(internal.read_restricted_policy()->>'version')::integer,'purpose','BASIC_INCIDENT_NOTE','sourceBasis','SCHOOL_AUTHORED','retentionStatus','SYNTHETIC_ONLY','retentionNote','Human owner reviews synthetic retention only','ownerId','20000000-0000-4000-8000-000000000001','reason','Admin approves technical synthetic records','confirmApproval',true),'restricted-policy',repeat('a',64),'restricted-test')is not null as approved;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into restricted_fixture(id)values((internal.restricted_record_command('create',null,'{"courseId":"99610000-0000-4000-8000-000000000001","learnerId":"20000000-0000-4000-8000-000000000012","occurredAt":"2026-10-01T12:00:00Z","title":"Factual school note","note":"Observed context only","confirmFactualRecord":true}','restricted-create',repeat('b',64),'restricted-test')->>'id')::uuid);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_restricted_records(25,null)$$,'42501',null,'parent cannot obtain restricted source rows');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select internal.restricted_record_command('approve',(select id from restricted_fixture),'{"expectedRevision":1,"followUpOwnerId":"20000000-0000-4000-8000-000000000004","instructions":"Teacher manually reviews the exact factual note","reason":"Policy owner approves manual followup","confirmApproval":true}','restricted-approve',repeat('c',64),'restricted-test')is not null as followed;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.restricted_record_command('followup',(select id from restricted_fixture),'{"expectedRevision":2,"status":"COMPLETED","note":"Assigned teacher completed the actual manual action","confirmManualAction":true}','restricted-followup',repeat('d',64),'restricted-test')is not null as completed;
select is(internal.read_restricted_records(25,null)->'items'->0->>'state','COMPLETED','manual action state remains human recorded');select ok(not has_table_privilege('authenticated','app.restricted_record_revisions','select'),'DataAPI restricted body grant denied');select ok(not has_table_privilege('cuevo_api','app.restricted_records','select'),'API raw restricted source grants denied');select ok(not has_function_privilege('cuevo_worker','internal.read_restricted_records(integer,uuid)','execute'),'worker cannot read restricted notes');reset role;
select is((select count(*)from app.restricted_record_revisions where record_id=(select id from restricted_fixture)),3::bigint,'author approval/manual action retain immutable revisions');select ok(not exists(select 1 from internal.audit_events where school_id='10000000-0000-4000-8000-000000000001'and metadata::text like'%Observed context only%'),'general audit metadata does not contain restricted note text');select*from finish();rollback;


